"<?php

namespace App\Filament\Widgets;

use Filament\Widgets\StatsOverviewWidget as BaseWidget;
use Filament\Widgets\StatsOverviewWidget\Stat;
use App\Models\Post;
use App\Models\Document;
use App\Models\User;
use App\Models\Category;

class StatsOverviewWidget extends BaseWidget
{
    protected function getStats(): array
    {
        $postCount = Post::count();
        $newPosts = Post::where('created_at', '>=', now()->subWeek())->count();
        $documentCount = Document::count();
        $userCount = User::count();
        $categoryCount = Category::count();

        return [
            Stat::make('Posts', $postCount)
                ->description("{$newPosts} new this week")
                ->descriptionIcon($newPosts > 0 ? 'heroicon-m-arrow-trending-up' : 'heroicon-m-arrow-trending-down')
                ->color($newPosts > 0 ? 'success' : 'gray')
                ->chart([7, 2, 10, 3, 15, 4, 17])
                ->url(route('filament.admin.resources.posts.index'), true),

            Stat::make('Documents', $documentCount)
                ->description('Official PDFs')
                ->icon('heroicon-o-document-text')
                ->color('primary')
                ->chart([3, 5, 2, 8, 14, 10, 15])
                ->url(route('filament.admin.resources.documents.index'), true),

            Stat::make('Users', $userCount)
                ->description('Admins & staff')
                ->icon('heroicon-o-users')
                ->color('danger')
                ->chart([1, 2, 2, 3, 4, 5, 6])
                ->url(route('filament.admin.resources.users.index'), true),

            Stat::make('Categories', $categoryCount)
                ->description('Content groups')
                ->icon('heroicon-o-tag')
                ->color('info')
                ->chart([2, 2, 3, 3, 3, 4, 4])
                ->url(route('filament.admin.resources.categories.index'), true),
        ];
    }
}"

