"<?php

namespace App\Filament\Widgets;

use Filament\Widgets\ChartWidget;
use App\Models\Post;

class PostsChart extends ChartWidget
{
    protected static ?string $heading = 'Posts Published This Year';
    protected static ?int $sort = 2; // Order after StatsOverviewWidget

    protected function getData(): array
    {
        $data = [];
        $months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

        for ($i = 1; $i <= 12; $i++) {
            $data[] = Post::whereMonth('created_at', $i)->whereYear('created_at', date('Y'))->count();
        }

        return [
            'datasets' => [
                [
                    'label' => 'Posts Created',
                    'data' => $data,
                    'backgroundColor' => '#0F479C',
                    'borderColor' => '#0F479C',
                ],
            ],
            'labels' => $months,
        ];
    }

    protected function getType(): string
    {
        return 'line';
    }
}"

