                    'created_at' => \Carbon\Carbon::parse($post->published_at ?? $post->created_at)->format('M d, Y'),
                ]),

            // Fetch 5 latest documents
            'latestDocuments' => \App\Models\Document::latest('published_date')
                ->take(5)
                ->get(),
        ]);
    }
