"@import url('https://fonts.googleapis.com/css2?family=Kantumruy+Pro:wght@400;700&display=swap');
@tailwind base;
@tailwind components;
@tailwind utilities;

body {
    font-family: 'Kantumruy Pro', sans-serif;
    @apply antialiased text-slate-800;
}

.filepond--file-info {
    display: none !important;
}

/* Hide filename and size inside Trix/RichEditor content on the frontend */
figcaption.attachment__caption {
    display: none !important;
}

/* ==========================================================================
   Vue Page Transitions
   ========================================================================== */
.page-fade-enter-active,
.page-fade-leave-active {
    transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}
.page-fade-enter-from {
    opacity: 0;
    transform: translateY(15px);
}
.page-fade-leave-to {
    opacity: 0;
    transform: translateY(-15px);
}

/* ==========================================================================
   Custom NProgress (Glowing Top Bar)
   ========================================================================== */
#nprogress {
    pointer-events: none;
}
#nprogress .bar {
